fn prepare_real_store(){let Some(path)=std::env::var_os("FK_G33_PREPARE")else{return;};let s=Store::create(Path::new(&path)).unwrap();let stage=s.staging_directory().unwrap();println!("G33_STAGE={}",stage.display());}

#[test]fn junction_directories_are_rejected_without_touching_target(){
 use std::os::windows::process::CommandExt;
 for name in ["staging","generations"]{let s=store(&format!("junction-{name}"));let target=s.root.parent().unwrap().join("foreign-fixture");fs::create_dir(&target).unwrap();fs::write(target.join("keep"),b"keep").unwrap();let(stage,m,h)=staged(&s,"one");fs::rename(s.root.join(name),s.root.parent().unwrap().join(format!("retained-{name}"))).unwrap();let status=std::process::Command::new(std::env::var_os("FK_G33_PYTHON").unwrap()).arg("-B").arg(std::env::var_os("FK_G33_JUNCTION_HELPER").unwrap()).arg(s.root.join(name).to_string_lossy().trim_start_matches(r"\\?\")).arg(target.to_string_lossy().trim_start_matches(r"\\?\")).creation_flags(0x08000000).output().unwrap();assert!(status.status.success(),"junction fixture creation: {:?}; root={:?}; target={:?}",status,s.root,target);if name=="staging"{assert!(s.staging_directory().is_err());}else{assert!(s.install(&stage,&m,&h).is_err());}assert_eq!(fs::read(target.join("keep")).unwrap(),b"keep");assert!(s.selection().unwrap().active.is_none());}
}
#[test]fn corrupted_previous_is_never_selected(){let s=store("bad-previous");let(p,m,h)=staged(&s,"one");s.install(&p,&m,&h).unwrap();let(p2,m2,h2)=staged(&s,"two");s.install(&p2,&m2,&h2).unwrap();fs::write(s.root.join("generations").join(&h).join("worker.txt"),b"bad").unwrap();assert!(s.rollback(&m,&h).is_err());assert!(s.acquire(&m2,&h2).is_ok());}
#[test]fn incomplete_publication_files_are_never_promoted(){let s=store("unpublished");let(p,m,h)=staged(&s,"one");s.install(&p,&m,&h).unwrap();fs::write(s.root.join("selection-foreign.pending"),b"{partial").unwrap();assert_eq!(s.selection().unwrap().active,Some(h.clone()));assert!(s.acquire(&m,&h).is_ok());assert_eq!(fs::read(s.root.join("selection-foreign.pending")).unwrap(),b"{partial");}
#[test]fn manifest_limits_and_unknown_fields_fail_closed(){let m=serde_json::to_vec(&Manifest{schema:1,component:"python-tools".into(),files:vec![Entry{path:"worker.txt".into(),bytes:LIMIT+1,sha256:hash(b"")}]}).unwrap();assert!(approved(&m,&hash(&m)).is_err());let bad=br#"{"schema":1,"component":"python-tools","files":[],"allowUnverified":true}"#;assert!(approved(bad,&hash(bad)).is_err());}
